CREATE TYPE "DevicePlatform" AS ENUM('IOS','ANDROID');CREATE TYPE "NotificationDigestMode" AS ENUM('IMMEDIATE','DAILY','WEEKLY','OFF');
CREATE TABLE "mobile_push_tokens"("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL REFERENCES "app_users"("id") ON DELETE CASCADE,"token" varchar(300) UNIQUE NOT NULL,"platform" "DevicePlatform" NOT NULL,"device_name" varchar(120),"active" boolean NOT NULL DEFAULT true,"last_seen_at" timestamptz(6) NOT NULL DEFAULT now(),"created_at" timestamptz(6) NOT NULL DEFAULT now());CREATE INDEX "mobile_push_tokens_user_id_active_idx" ON "mobile_push_tokens"("user_id","active");
CREATE TABLE "notification_preferences"("user_id" uuid PRIMARY KEY REFERENCES "app_users"("id") ON DELETE CASCADE,"transactional_push" boolean NOT NULL DEFAULT true,"transactional_email" boolean NOT NULL DEFAULT true,"transactional_sms" boolean NOT NULL DEFAULT false,"marketing_push" boolean NOT NULL DEFAULT false,"marketing_email" boolean NOT NULL DEFAULT false,"quiet_hours_start" varchar(5),"quiet_hours_end" varchar(5),"timezone" varchar(60) NOT NULL DEFAULT 'Asia/Kolkata',"digest_mode" "NotificationDigestMode" NOT NULL DEFAULT 'IMMEDIATE',"updated_at" timestamptz(6) NOT NULL DEFAULT now(),CHECK("quiet_hours_start" IS NULL OR "quiet_hours_start"~'^([01][0-9]|2[0-3]):[0-5][0-9]$'),CHECK("quiet_hours_end" IS NULL OR "quiet_hours_end"~'^([01][0-9]|2[0-3]):[0-5][0-9]$'));
ALTER TABLE "mobile_push_tokens" ENABLE ROW LEVEL SECURITY;ALTER TABLE "notification_preferences" ENABLE ROW LEVEL SECURITY;REVOKE ALL ON "mobile_push_tokens","notification_preferences" FROM anon,authenticated;
